import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import zhCN from './zh-CN.json';
import en from './en.json';

// YEmusic shim (replaces Folia's src/i18n/config.ts).
// Folia ships a 4,700-key dictionary in three languages plus a language detector. The vendored
// visualizers only use a few hundred of those keys, so zh-CN.json / en.json are trimmed to exactly
// the keys they reference (generated by scripts/gen-folia-locales.mjs, see VENDOR.md in this folder). YEmusic's UI is
// Chinese, so zh-CN is the active language and English is the per-key fallback.

// Keys the vendored panels reference that Folia itself never defined (it renders the raw key).
const extras = {
    'zh-CN': { common: { reset: '恢复默认' } },
    en: { common: { reset: 'Reset to default' } },
};

const merge = (base: Record<string, unknown>, extra: Record<string, unknown>): Record<string, unknown> => {
    const out: Record<string, unknown> = { ...base };
    for (const [key, value] of Object.entries(extra)) {
        const existing = out[key];
        out[key] = value && typeof value === 'object' && existing && typeof existing === 'object'
            ? merge(existing as Record<string, unknown>, value as Record<string, unknown>)
            : value;
    }
    return out;
};

if (!i18n.isInitialized) {
    void i18n
        .use(initReactI18next)
        .init({
            resources: {
                'zh-CN': { translation: merge(zhCN, extras['zh-CN']) },
                en: { translation: merge(en, extras.en) },
            },
            lng: 'zh-CN',
            fallbackLng: 'en',
            supportedLngs: ['zh-CN', 'en'],
            parseMissingKeyHandler: (key: string, defaultValue?: string): string => defaultValue ?? key,
            interpolation: { escapeValue: false },
            initAsync: false,
        });
}

export default i18n;
